{
  "name": "rf_channel_update",
  "confidence": "medium",
  "docstring": "Validate and enqueue a per-channel RF update by filling the channel request slot and radio descriptor, then write the descriptor pointer to the baseband RF slot and trigger the update.",
  "subsystem": "rf",
  "var_renames": {
    "a1": "channel",
