    "a3": "dwell_time",
    "v3": "channel_index",
    "v4": "request_slot",
    "v5": "rf_reg_base",
    "v7": "rf_descriptor",
    "v8": "dwell_limit",
    "v9": "channel_reg_base",
    "v10": "descriptor_status"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "request_slot: busy/in-use word (must be zero)"
    },
    {
      "offset": 4,
      "meaning": "request_slot: dwell/time parameter copied from a3"
    },
    {
      "offset": 8,
      "meaning": "request_slot: armed/pending flag set to 1"
    },
    {
      "offset": 0,
      "meaning": "rf_descriptor: 16-bit dwell/time value from a3"
    },
    {
      "offset": 3,
      "meaning": "rf_descriptor: status byte updated with 0xE while preserving 0x31 bits"
    },
    {
      "offset": 4,
      "meaning": "rf_descriptor: pointer to 4-byte-aligned params"
    }
  ]
}
